import{_ as i,c as t,o as a,ag as s}from"./chunks/framework.Bzez9NG9.js";const g=JSON.parse('{"title":"Git","description":"Use Git with SPACE Python and Jupyter projects, including repository workflow and SSH configuration for client-managed SPACE installations.","frontmatter":{"title":"Git","description":"Use Git with SPACE Python and Jupyter projects, including repository workflow and SSH configuration for client-managed SPACE installations.","keywords":["Git","JupyterLab Git","jupyter-git","source control","SSH","SSH key","gitconfig","Python","notebooks"],"outline":"deep"},"headers":[],"relativePath":"doc/python/git.md","filePath":"doc/python/git.md"}'),n={name:"doc/python/git.md"};function o(r,e,p,l,h,c){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h1><p>SPACE uses the native JupyterLab Git integration for source control of Python projects, scripts, notebooks, and related files.</p><p>This Git workflow is intended for files in the SPACE Python workspace. It is separate from the <a href="./../planning-analytics/git.html">Planning Analytics Git integration</a>, which manages IBM Planning Analytics model assets.</p><h2 id="repository-workflow" tabindex="-1">Repository workflow <a class="header-anchor" href="#repository-workflow" aria-label="Permalink to &quot;Repository workflow&quot;">​</a></h2><p>Use a Git repository for Python files that should be versioned or shared between developers.</p><p>A single repository for the client Python workspace is the recommended starting point. <code>git</code> is a suggested repository folder name, but the repository can use another folder when required by the project.</p><p>Use the JupyterLab Git interface for normal repository operations such as:</p><ul><li>reviewing changed files;</li><li>staging changes;</li><li>committing;</li><li>pulling remote changes;</li><li>pushing commits;</li><li>working with branches.</li></ul><p>Because SPACE uses the native Git extension, developers can use familiar Git concepts without a separate SPACE-specific source-control workflow.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Private repositories require Git credentials to be configured for the SPACE Python environment.</p><p>For SSH-based authentication, use a dedicated SSH key for the SPACE installation and grant its public key the appropriate repository access in the Git hosting platform.</p><p>Succeedium-managed SPACE environments can have this configuration managed as part of the deployment. Administrators of client-managed SPACE installations can configure it using the server-side files described below.</p><h2 id="client-managed-space-configuration" tabindex="-1">Client-managed SPACE configuration <a class="header-anchor" href="#client-managed-space-configuration" aria-label="Permalink to &quot;Client-managed SPACE configuration&quot;">​</a></h2><p>For client-managed installations, keep Python Git configuration under:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config/python/git/</span></span>
<span class="line"><span>├── .gitconfig</span></span>
<span class="line"><span>├── id_ed25519</span></span>
<span class="line"><span>├── id_ed25519.pub</span></span>
<span class="line"><span>├── known_hosts</span></span>
<span class="line"><span>└── ssh_config</span></span></code></pre></div><p>This keeps the Git configuration outside the SPACE application image and separates it from application source code.</p><p>The directory can be mounted read-only into the Python service:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./config/python/git:/space-git:ro</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  GIT_CONFIG_GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/space-git/.gitconfig</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  GIT_SSH_COMMAND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ssh -F /space-git/ssh_config&quot;</span></span></code></pre></div><p><code>GIT_CONFIG_GLOBAL</code> tells Git to use the installation-specific global configuration.</p><p><code>GIT_SSH_COMMAND</code> directs Git SSH operations through the supplied SSH configuration.</p><h2 id="generate-an-ssh-key" tabindex="-1">Generate an SSH key <a class="header-anchor" href="#generate-an-ssh-key" aria-label="Permalink to &quot;Generate an SSH key&quot;">​</a></h2><p>On the SPACE server, generate a dedicated Ed25519 key pair for Git access:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/id_ed25519</span></span></code></pre></div><p>Use an appropriate deployment-specific comment or key-management convention if required by your organization.</p><p>Add the generated public key, <code>id_ed25519.pub</code>, to the Git provider or repository with only the permissions required by the SPACE environment.</p><p>Keep the private key on the SPACE server.</p><h2 id="ssh-configuration" tabindex="-1">SSH configuration <a class="header-anchor" href="#ssh-configuration" aria-label="Permalink to &quot;SSH configuration&quot;">​</a></h2><p>Configure <code>ssh_config</code> to use the mounted key for the required Git host. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host github.com</span></span>
<span class="line"><span>    HostName github.com</span></span>
<span class="line"><span>    User git</span></span>
<span class="line"><span>    IdentityFile /space-git/id_ed25519</span></span>
<span class="line"><span>    IdentitiesOnly yes</span></span>
<span class="line"><span>    UserKnownHostsFile /space-git/known_hosts</span></span></code></pre></div><p>Replace the host when using another Git provider.</p><p>Populate <code>known_hosts</code> with the verified SSH host key for the Git provider according to your organization&#39;s security process.</p><h2 id="git-identity" tabindex="-1">Git identity <a class="header-anchor" href="#git-identity" aria-label="Permalink to &quot;Git identity&quot;">​</a></h2><p>Use <code>.gitconfig</code> to configure the Git identity and other installation-level settings required for commits.</p><p>For example:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[user]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = SPACE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = space@example.com</span></span></code></pre></div><p>Use an identity appropriate for the client environment and repository workflow.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Treat the SSH private key as an infrastructure credential.</p><ul><li>keep it under the local SPACE server configuration;</li><li>do not commit it to the SPACE application repository or client Python repository;</li><li>do not bake it into a Docker image;</li><li>mount the Git configuration read-only where possible;</li><li>grant the key only the repository permissions the environment requires.</li></ul><p>SPACE Python secrets are intended for credentials consumed by Python code at runtime. Git SSH authentication is infrastructure configuration used by Git itself, so the SSH private key should remain in the server-side Git configuration rather than being retrieved by Python code as a SPACE secret.</p>`,41)]))}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
